const root=document.documentElement;
try{root.dataset.theme=localStorage.getItem('ap-theme')||'cream'}catch{}
const theme=document.querySelector('.themepick');
function labelTheme(){if(theme){const label=root.dataset.theme==='cream'?'Switch to dark':'Switch to light';theme.setAttribute('aria-label',label);theme.title=label}}
labelTheme();theme?.addEventListener('click',()=>{root.dataset.theme=root.dataset.theme==='cream'?'mocha':'cream';try{localStorage.setItem('ap-theme',root.dataset.theme)}catch{}labelTheme()});
document.querySelectorAll('.job__toggle').forEach(b=>b.addEventListener('click',()=>{const job=b.closest('.job');const open=job.dataset.open!=='1';job.dataset.open=open?'1':'0';b.setAttribute('aria-expanded',String(open))}));
const burger=document.querySelector('.burger');if(burger){const menu=document.createElement('nav');menu.className='mobile-menu';menu.id='site-drawer';menu.innerHTML=document.querySelector('.bar nav').innerHTML;document.querySelector('.site').append(menu);burger.addEventListener('click',()=>{const open=menu.classList.toggle('open');burger.setAttribute('aria-expanded',String(open));burger.setAttribute('aria-label',open?'Close menu':'Open menu')});menu.addEventListener('click',e=>{if(e.target.closest('a')){menu.classList.remove('open');burger.setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.classList.remove('open');burger.setAttribute('aria-expanded','false')}})}
const sections=document.querySelectorAll('section[id]');const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('.bar nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}},{rootMargin:'-15% 0px -60% 0px'});sections.forEach(s=>observer.observe(s));
